[DATA] that lastOrder.total.currency.symbol is non-empty {OBSERVED}

[ERRORS] errors[] empty {DOC}
[DATA] the item with organizationId = @td(ORG_ACME.id) has address.line1 = @td(ORG_ACME.line1) {DOC}
[DATA] that item's address.city = @td(ORG_ACME.city) {DOC}
